-- بيانات مقرر فيزياء 3-2 (المقرر 104، قيد الإعداد) — الجزء 2 من 2. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-phys32-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C1-L2-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'تُشغَّل مدفأة كهربائية قدرتها 2.0 kW مدة 3.0 h يوميًا. إذا كان ثمن الكيلوواط.ساعة 0.18 ريال، فما تكلفة تشغيلها مدة 30 يومًا؟', null, null, '["$32$ ريالًا","$1.1$ ريال","$3.2\\times10^{4}$ ريال","$1.8\\times10^{2}$ ريال"]'::jsonb, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 29 — مسائل تدريبية (تكلفة الطاقة)'),
('mcq', 2, 'يسحب جهاز كهربائي تيارًا مقداره 5.0 A من مصدر جهده 220 V، ويعمل 4.0 h يوميًا. ما تكلفة تشغيله مدة 30 يومًا إذا كان ثمن الكيلوواط.ساعة 0.18 ريال؟', null, null, '["$0.79$ ريال","$24$ ريالًا","$5.9$ ريال","$2.4\\times10^{4}$ ريال"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 29 — مسائل تدريبية (تكلفة الطاقة)'),
('mcq', 3, 'يمثل الشكل الآتي دائرة فرن كهربائي. يعمل الفرن 2.0 h يوميًا، وثمن الكيلوواط.ساعة 0.18 ريال. ما قيمة الفاتورة الشهرية (30 يومًا) لتشغيل الفرن؟', null, '[{"src":"qimg/phys32/c1l2-o05-oven.svg","alt":"دائرة كهربائية مستطيلة: في الضلع الأيسر بطارية (ألواح طويلة وقصيرة متناوبة، والطرف الموجب أعلى) مكتوب بجانبها 220 V، وفي الضلع الأيمن مقاومة متعرجة مكتوب بجانبها 11 Ω وعبارة «عنصر الفرن»، وأسفل الدائرة سهم أفقي نحو اليسار مكتوب تحته I."}]'::jsonb, '["$1.6$ ريال","$0.22$ ريال","$48$ ريالًا","$4.8\\times10^{4}$ ريال"]'::jsonb, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 36 — السؤال 68'),
('mcq', 4, 'يكلّف تشغيل مكيّف هواء 54 ريالًا خلال 30 يومًا، وهو يعمل 10 h يوميًا، وثمن الكيلوواط.ساعة 0.18 ريال. ما قدرة المكيّف؟', null, null, '["$30\\ \\text{kW}$","$0.18\\ \\text{kW}$","$1.0\\ \\text{W}$","$1.0\\ \\text{kW}$"]'::jsonb, 'تحليل', 'حل مسألة عكسية', 'صعب', 'الكتاب ص 37 — السؤال 69'),
('mcq', 5, 'بطارية جهدها 9.0 V ثمنها 12.00 ريالًا، تزوّد جهازًا بتيار مقداره 0.0400 A مدة 250.0 h قبل أن تنفد. ما تكلفة كل kWh تزوّدنا به هذه البطارية؟', null, null, '["$0.13$ ريال","$1.3\\times10^{2}$ ريال","$1.1$ ريال","$3.7\\times10^{-5}$ ريال"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 36 — السؤال 64'),
('mcq', 6, 'يبين الشكل الآتي قراءتي عداد الكهرباء في منزل في بداية شهر ونهايته. إذا كان ثمن الكيلوواط.ساعة 0.18 ريال، فما تكلفة الطاقة المستهلكة خلال الشهر؟', null, '[{"src":"qimg/phys32/c1l2-o05-meter.svg","alt":"شاشتان رقميتان لعداد الكهرباء: اليمنى بعنوان «القراءة في بداية الشهر» وتعرض 24365، واليسرى بعنوان «القراءة في نهاية الشهر» وتعرض 24965، وتحت كل منهما الوحدة kWh."}]'::jsonb, '["$4.5\\times10^{3}$ ريال","$6.0\\times10^{2}$ ريال","$1.1\\times10^{2}$ ريال","$3.3\\times10^{3}$ ريال"]'::jsonb, 'تطبيق', 'استنتاج من شكل', 'سهل', 'الكتاب ص 27 — الشكل 1-10 (عداد الكيلوواط.ساعة)'),
('mcq', 7, 'يُستبدل مصباح متوهج قدرته 100 W بمصباح موفّر قدرته 20 W يعطي الإضاءة نفسها، ويعمل المصباح 5.0 h يوميًا. إذا كان ثمن الكيلوواط.ساعة 0.18 ريال، فما مقدار التوفير في التكلفة خلال 30 يومًا؟', null, null, '["$2.2$ ريال","$2.7$ ريال","$0.54$ ريال","$2.2\\times10^{3}$ ريال"]'::jsonb, 'تحليل', 'حل مسألة', 'متوسط', 'الكتاب ص 27 — أنواع المصابيح'),
('essay', 1, 'يمر تيار كهربائي مقداره 10.0 A في مدفأة كهربائية عند وصلها بمصدر فرق جهده 220 V، وتُشغَّل بمتوسط 5.0 h يوميًا. احسب: (a) القدرة التي تستهلكها المدفأة. (b) الطاقة المستهلكة في 30 يومًا بوحدة kWh. (c) تكلفة تشغيلها مدة 30 يومًا إذا كان ثمن الكيلوواط.ساعة 0.18 ريال.', null, null, null, 'تطبيق', 'مسألة متعددة الخطوات', 'سهل', 'الكتاب ص 29 — المسألة 25'),
('essay', 2, 'يبين الجدول الآتي قدرات بعض الأجهزة في منزل وعدد ساعات تشغيلها يوميًا. إذا كان ثمن الكيلوواط.ساعة 0.18 ريال: (a) احسب الطاقة اليومية التي يستهلكها كل جهاز. (b) احسب التكلفة الكلية لتشغيل الأجهزة الأربعة مدة 30 يومًا. (c) حدّد الجهاز الذي يكلّف أكثر، واقترح طريقة لخفض فاتورته.', '{"headers":["الجهاز","القدرة (kW)","ساعات التشغيل اليومية (h)"],"rows":[["مكيّف هواء","1.8","8.0"],["ثلاجة","0.20","24"],["غسالة ملابس","0.50","1.0"],["مصابيح الإنارة معًا","0.30","6.0"]]}'::jsonb, null, null, 'تحليل', 'تحليل بيانات', 'متوسط', 'الكتاب ص 28 — تكلفة تشغيل الأجهزة'),
('essay', 3, 'يعمل مذياع على بطارية جهدها 6.0 V ثمنها 15.00 ريالًا، وتزوده بتيار مقداره 0.10 A مدة 200 h قبل أن تنفد. (a) احسب تكلفة كل kWh تزوّدنا به البطارية. (b) إذا شُغِّل المذياع نفسه المدة نفسها بمحوّل موصول بدائرة المنزل وثمن الكيلوواط.ساعة 0.18 ريال، فاحسب التكلفة. (c) قوّم: أيّ الطريقتين أفضل اقتصاديًا؟ ومتى تُفضَّل البطارية رغم ذلك؟', null, null, null, 'تقويم', 'مقارنة وتقويم', 'صعب', 'الكتاب ص 37 — السؤال 70')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C1-L2-O05') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, '$E = Pt = (2.0\ \text{kW})(3.0\ \text{h})(30) = 180\ \text{kWh}$، والتكلفة $= (180\ \text{kWh})(0.18\ \text{ريال/kWh}) = 32$ ريالًا تقريبًا.', '["","حسب تكلفة يوم واحد فقط ونسي الضرب في 30 يومًا.","عوّض القدرة بالواط (2000) بدل الكيلوواط.","حسب الطاقة 180 kWh وكتبها تكلفةً دون الضرب في ثمن الكيلوواط.ساعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-24T23:08:04.858Z"}'::jsonb),
('mcq', 2, 1, '$P = IV = (5.0\ \text{A})(220\ \text{V}) = 1.1\ \text{kW}$، $E = (1.1\ \text{kW})(4.0\ \text{h})(30) = 132\ \text{kWh}$، والتكلفة $= 132\times0.18 = 24$ ريالًا تقريبًا.', '["حسب تكلفة يوم واحد فقط.","","نسي الضرب في عدد ساعات التشغيل اليومية.","عوّض القدرة بالواط بدل الكيلوواط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-24T23:08:04.858Z"}'::jsonb),
('mcq', 3, 2, '$P = \frac{V^2}{R} = \frac{(220\ \text{V})^2}{11\ \Omega} = 4.4\ \text{kW}$، $E = (4.4\ \text{kW})(2.0\ \text{h})(30) = 264\ \text{kWh}$، والتكلفة $= 264\times0.18 = 48$ ريالًا تقريبًا.', '["حسب تكلفة يوم واحد فقط.","حسب القدرة $\\frac{V}{R} = 20\\ \\text{W}$ دون تربيع الجهد.","","عوّض القدرة بالواط بدل الكيلوواط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-24T23:08:04.859Z"}'::jsonb),
('mcq', 4, 3, 'الطاقة $= \frac{54}{0.18} = 300\ \text{kWh}$، وزمن التشغيل $= (10\ \text{h})(30) = 300\ \text{h}$، إذن $P = \frac{E}{t} = \frac{300\ \text{kWh}}{300\ \text{h}} = 1.0\ \text{kW}$.', '["قسم الطاقة على ساعات يوم واحد فقط (10 h) لا على 300 h.","قسم التكلفة على عدد الساعات ونسي القسمة على ثمن الكيلوواط.ساعة.","الناتج بالكيلوواط لا بالواط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-24T23:08:04.859Z"}'::jsonb),
('mcq', 5, 1, '$E = IVt = (0.0400\ \text{A})(9.0\ \text{V})(250.0\ \text{h}) = 90\ \text{Wh} = 0.090\ \text{kWh}$، وتكلفة الكيلوواط.ساعة $= \frac{12.00}{0.090} = 1.3\times10^{2}$ ريال؛ أي أغلى كثيرًا من كهرباء المنزل.', '["قسم الثمن على الطاقة بالواط.ساعة (90) دون تحويلها إلى kWh.","","ضرب الثمن في الطاقة بدل أن يقسمه عليها.","حسب تكلفة الجول الواحد لا الكيلوواط.ساعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-24T23:08:04.859Z"}'::jsonb),
('mcq', 6, 2, 'الطاقة المستهلكة $= 24965 - 24365 = 600\ \text{kWh}$، والتكلفة $= (600)(0.18) = 108 \approx 1.1\times10^{2}$ ريال.', '["ضرب قراءة نهاية الشهر كلها في الثمن بدل الفرق بين القراءتين.","حسب الطاقة المستهلكة 600 kWh ولم يضربها في الثمن.","","قسم الطاقة على الثمن بدل أن يضربها فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-24T23:08:04.860Z"}'::jsonb),
('mcq', 7, 0, 'فرق القدرة $= 100 - 20 = 80\ \text{W} = 0.080\ \text{kW}$، وزمن التشغيل $= (5.0)(30) = 150\ \text{h}$، فالطاقة الموفَّرة $= (0.080)(150) = 12\ \text{kWh}$، والتوفير $= (12)(0.18) = 2.2$ ريال.', '["","هذه تكلفة تشغيل المصباح المتوهج وحده لا التوفير.","هذه تكلفة تشغيل المصباح الموفّر وحده.","عوّض فرق القدرة بالواط بدل الكيلوواط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-24T23:08:04.860Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $P = IV = (10.0\ \text{A})(220\ \text{V}) = 2.2\times10^{3}\ \text{W} = 2.2\ \text{kW}$. (b) $E = Pt = (2.2\ \text{kW})(5.0\ \text{h})(30) = 3.3\times10^{2}\ \text{kWh}$. (c) التكلفة $= (330\ \text{kWh})(0.18\ \text{ريال/kWh}) = 59$ ريالًا تقريبًا.', '["القدرة 2.2 kW","الطاقة 330 kWh","التكلفة نحو 59 ريالًا"]'::jsonb, '["$P = 10.0\\times220 = 2200\\ \\text{W} = 2.2\\ \\text{kW}$","$t = 5.0\\times30 = 150\\ \\text{h}$","$E = 2.2\\times150 = 330\\ \\text{kWh}$","التكلفة $= 330\\times0.18 = 59.4 \\approx 59$ ريالًا"]'::jsonb, '[{"element":"حساب القدرة","marks":1},{"element":"حساب الطاقة بوحدة kWh","marks":2},{"element":"حساب التكلفة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الخطوات الثلاث صحيحة بالوحدات."},{"level":"2–3 درجات","description":"خطأ في تحويل الواط إلى كيلوواط أو في عدد الساعات."},{"level":"1 درجة","description":"القدرة فقط صحيحة."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["إبقاء القدرة بالواط عند حساب kWh.","نسيان الضرب في عدد الأيام.","قسمة الطاقة على الثمن."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-24T23:08:04.860Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) المكيّف: $(1.8)(8.0) = 14.4\ \text{kWh}$؛ الثلاجة: $(0.20)(24) = 4.8\ \text{kWh}$؛ الغسالة: $(0.50)(1.0) = 0.50\ \text{kWh}$؛ المصابيح: $(0.30)(6.0) = 1.8\ \text{kWh}$. (b) المجموع اليومي $21.5\ \text{kWh}$، وفي 30 يومًا $645\ \text{kWh}$، والتكلفة $= (645)(0.18) = 116 \approx 1.2\times10^{2}$ ريال. (c) المكيّف أكثرها تكلفة (نحو 78 ريالًا شهريًا) لأن حاصل ضرب قدرته في زمن تشغيله أكبر؛ ويمكن خفض فاتورته بتقليل ساعات تشغيله أو اختيار مكيّف أقل قدرة (أعلى كفاءة).', '["الطاقة اليومية لكل جهاز","المجموع الشهري 645 kWh","التكلفة نحو $1.2\\times10^{2}$ ريال (116)","المكيّف الأكثر تكلفة مع تعليل واقتراح"]'::jsonb, '["طاقة كل جهاز $= P\\times t$ اليومي","المجموع اليومي $= 14.4 + 4.8 + 0.50 + 1.8 = 21.5\\ \\text{kWh}$","الشهري $= 21.5\\times30 = 645\\ \\text{kWh}$","التكلفة $= 645\\times0.18 = 116.1 \\approx 1.2\\times10^{2}$ ريال"]'::jsonb, '[{"element":"الطاقة اليومية للأجهزة","marks":2},{"element":"الطاقة الشهرية والتكلفة","marks":2},{"element":"تحديد الجهاز والتعليل والاقتراح","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة كاملة مع تحديد الجهاز واقتراح مسوّغ."},{"level":"3–4 درجات","description":"حسابات صحيحة مع خطأ في التكلفة أو دون اقتراح."},{"level":"1–2 درجة","description":"طاقة بعض الأجهزة فقط."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["الحكم بأن الجهاز الأعلى قدرة هو الأعلى تكلفة دائمًا دون النظر إلى زمن التشغيل.","نسيان ساعات تشغيل الثلاجة الطويلة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-24T23:08:04.861Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $E = IVt = (0.10\ \text{A})(6.0\ \text{V})(200\ \text{h}) = 120\ \text{Wh} = 0.12\ \text{kWh}$، وتكلفة الكيلوواط.ساعة $= \frac{15.00}{0.12} = 1.3\times10^{2}$ ريال. (b) التكلفة $= (0.12\ \text{kWh})(0.18) = 0.022$ ريال. (c) كهرباء المنزل أرخص بنحو 700 مرة، فهي أفضل اقتصاديًا؛ لكن البطارية تُفضَّل حين يلزم نقل الجهاز وتشغيله بعيدًا عن مصادر التيار.', '["الطاقة 0.12 kWh","تكلفة الكيلوواط.ساعة من البطارية نحو $1.3\\times10^{2}$ ريال","تكلفة التشغيل من المنزل نحو 0.022 ريال","حكم مسوّغ مع ذكر ميزة البطارية"]'::jsonb, '["$E = 0.10\\times6.0\\times200 = 120\\ \\text{Wh} = 0.12\\ \\text{kWh}$","$\\frac{15.00}{0.12} = 125 \\approx 1.3\\times10^{2}$ ريال لكل kWh","$0.12\\times0.18 = 0.0216 \\approx 0.022$ ريال","$\\frac{125}{0.18} \\approx 7\\times10^{2}$"]'::jsonb, '[{"element":"حساب الطاقة","marks":1},{"element":"تكلفة الكيلوواط.ساعة من البطارية","marks":1},{"element":"تكلفة التشغيل من المنزل","marks":1},{"element":"التقويم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة وتقويم متوازن."},{"level":"2–3 درجات","description":"حسابان صحيحان مع تقويم ناقص."},{"level":"1 درجة","description":"عنصر واحد صحيح."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["نسيان تحويل Wh إلى kWh.","ضرب ثمن البطارية في الطاقة بدل القسمة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-24T23:08:04.861Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C1-L2-O05') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C1-L2-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'لماذا ترتفع درجة حرارة مقاومة عند مرور تيار كهربائي فيها؟', null, null, '["لأن الإلكترونات تتصادم مع ذرات المقاومة فتزداد الطاقة الحركية للذرات","لأن جزءًا من الشحنات الكهربائية يفنى داخل المقاومة فتتحرر طاقته","لأن الإلكترونات تتجمع داخل المقاومة فيرتفع جهدها تدريجيًا","لأن المقاومة تولّد طاقة جديدة تضاف إلى طاقة المصدر"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 23 — تسخين مقاومة'),
('mcq', 2, 'بتعويض $V = IR$ في معادلة القدرة الكهربائية $P = IV$ نحصل على:', null, null, '["$P = IR^2$","$P = \\frac{I^2}{R}$","$P = I^2R$","$P = \\frac{R}{I^2}$"]'::jsonb, 'فهم', 'اشتقاق', 'سهل', 'الكتاب ص 24 — اشتقاق علاقتي القدرة'),
('mcq', 3, 'إذا علمت فرق الجهد $V$ بين طرفي مقاومة ومقدارها $R$ ولم تعلم التيار، فبتعويض $I = \frac{V}{R}$ في $P = IV$ تحصل على:', null, null, '["$P = V^2R$","$P = \\frac{V^2}{R}$","$P = \\frac{V}{R^2}$","$P = \\frac{R}{V^2}$"]'::jsonb, 'فهم', 'اشتقاق', 'متوسط', 'الكتاب ص 24 — اشتقاق علاقتي القدرة'),
('mcq', 4, 'يمر تيار في مقاومة ثابتة المقدار. إذا تضاعف التيار المار فيها، فكيف تتغير القدرة المستهلكة فيها؟', null, null, '["تزداد إلى مثلي قيمتها","تبقى مساوية لقيمتها","تقل إلى نصف قيمتها","تزداد إلى أربعة أمثالها"]'::jsonb, 'فهم', 'استدلال', 'متوسط', 'الكتاب ص 24 — اشتقاق علاقتي القدرة'),
('mcq', 5, 'سلكان أحدهما مقاومته كبيرة والآخر مقاومته صغيرة، وُصل كل منهما وحده بقطبي بطارية جهدها 6.0 V. أيّ السلكين ينتج طاقة حرارية بمعدل أكبر؟', null, null, '["السلك ذو المقاومة الكبيرة لأن $P = I^2R$","السلكان متساويان لأن الجهد نفسه","السلك ذو المقاومة الصغيرة لأن $P = \\frac{V^2}{R}$","لا يمكن الحكم دون معرفة التيار المار في كل منهما"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 35 — السؤال 53'),
('mcq', 6, 'تُمثَّل في الشكل الآتي أربعة منحنيات للقدرة $P$ مقابل التيار $I$. أيّ منحنى يمثل القدرة المستهلكة في مقاومة ثابتة المقدار مع تغير التيار المار فيها؟', null, '[{"src":"qimg/phys32/c1l2-o06-p-i.svg","alt":"أربعة رسوم بيانية صغيرة متجاورة، في كل منها محور أفقي مكتوب عنده I ومحور رأسي مكتوب عنده P: الرسم (A) خط مستقيم مائل يبدأ من نقطة الأصل؛ الرسم (B) منحنى يبدأ من نقطة الأصل أفقيًا تقريبًا ثم يزداد ميله تدريجيًا (قطع مكافئ)؛ الرسم (C) خط أفقي فوق المحور الأفقي؛ الرسم (D) منحنى يبدأ مرتفعًا عند المحور الرأسي ويتناقص مع زيادة I."}]'::jsonb, '["المنحنى (A)","المنحنى (B)","المنحنى (C)","المنحنى (D)"]'::jsonb, 'تحليل', 'استنتاج من منحنى', 'متوسط', 'الكتاب ص 24 — اشتقاق علاقتي القدرة'),
('mcq', 7, 'يعمل مجفف شعر على مصدر جهده 120 V، وفيه خياران: حار ودافئ. في أيّ الخيارين تكون مقاومة عنصر التسخين أصغر؟', null, null, '["في الخيار الحار لأن $P = \\frac{V^2}{R}$ أكبر عندما تكون $R$ أصغر","في الخيار الدافئ لأن المقاومة الصغيرة تنتج حرارة أقل","في الخيار الدافئ لأن $P = I^2R$ تتناسب طرديًا مع $R$","المقاومة متساوية في الخيارين لأن الجهد واحد"]'::jsonb, 'فهم', 'تطبيق حياتي', 'صعب', 'الكتاب ص 29 — السؤال 29'),
('essay', 1, 'وضّح كيف تتحوّل الطاقة الكهربائية إلى طاقة حرارية عند مرور تيار في مقاومة، واذكر جهازين منزليين صُمِّما للاستفادة من هذا التحوّل.', null, null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 23 — تسخين مقاومة'),
('essay', 2, 'ابدأ بالعلاقتين $P = IV$ و$V = IR$، واستنتج العلاقتين $P = I^2R$ و$P = \frac{V^2}{R}$، ثم وضّح متى يُفضَّل استعمال كل منهما.', null, null, null, 'فهم', 'اشتقاق', 'متوسط', 'الكتاب ص 24 — اشتقاق علاقتي القدرة'),
('essay', 3, 'قلّ فرق الجهد المطبق على مقاومة ثابتة المقدار إلى النصف. (a) حدّد مقدار التغير في التيار المار فيها. (b) حدّد مقدار التغير في القدرة المستهلكة. (c) فسّر لماذا لا تقل القدرة إلى النصف فقط.', null, null, null, 'تحليل', 'استدلال', 'صعب', 'الكتاب ص 29 — السؤال 30')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C1-L2-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'تسخن المقاومة بسبب تصادم الإلكترونات مع ذراتها، فتعمل هذه التصادمات على زيادة الطاقة الحركية للذرات، فترتفع درجة حرارة المقاومة؛ أي تتحول الطاقة الكهربائية إلى طاقة حرارية.', '["","الشحنة محفوظة ولا تفنى؛ الشحنات تفقد جزءًا من طاقة وضعها فقط.","الشحنات لا تتجمع في المقاومة؛ التيار متساوٍ عند طرفيها.","المقاومة لا تولّد طاقة بل تحوّل الطاقة الكهربائية إلى حرارية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.861Z"}'::jsonb),
('mcq', 2, 2, '$P = IV = I(IR) = I^2R$؛ فالقدرة تساوي مربع التيار مضروبًا في المقاومة.', '["ربّع المقاومة بدل التيار.","قسم على المقاومة بدل الضرب فيها.","","قلب العلاقة كلها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-24T23:08:04.862Z"}'::jsonb),
('mcq', 3, 1, '$P = IV = \left(\frac{V}{R}\right)V = \frac{V^2}{R}$؛ فالقدرة تساوي مربع الجهد مقسومًا على المقاومة.', '["ضرب في المقاومة بدل القسمة عليها.","","ربّع المقاومة بدل الجهد.","قلب الكسر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.862Z"}'::jsonb),
('mcq', 4, 3, '$P = I^2R$، فالقدرة تتناسب مع مربع التيار عند ثبات المقاومة: $(2)^2 = 4$؛ أي تزداد إلى أربعة أمثالها.', '["عدّ القدرة متناسبة طرديًا مع التيار، وهي تتناسب مع مربعه.","المقاومة ثابتة لكن القدرة تتغير بتغير التيار.","عكس التناسب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-24T23:08:04.862Z"}'::jsonb),
('mcq', 5, 2, 'الجهد ثابت (6.0 V) لكلا السلكين، فالعلاقة المناسبة $P = \frac{V^2}{R}$؛ والقدرة تتناسب عكسيًا مع المقاومة، فالسلك ذو المقاومة الصغيرة يمر فيه تيار أكبر وينتج طاقة بمعدل أكبر.', '["استعمل $P = I^2R$ كأن التيار واحد في السلكين، مع أن التيار في السلك الأصغر مقاومة أكبر.","تساوي الجهد لا يعني تساوي القدرة لأن المقاومتين مختلفتان.","","الجهد والمقاومة معلومان نوعيًا، و$P = \\frac{V^2}{R}$ تكفي للحكم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-24T23:08:04.862Z"}'::jsonb),
('mcq', 6, 1, '$P = I^2R$ ومع ثبات $R$ تتناسب القدرة مع مربع التيار، فالمنحنى قطع مكافئ يبدأ من نقطة الأصل ويزداد ميله، وهو المنحنى (B).', '["الخط المستقيم يعني تناسبًا طرديًا مع $I$، والقدرة تتناسب مع $I^2$.","","القدرة لا تبقى ثابتة عند تغير التيار في مقاومة ثابتة.","القدرة تزداد بزيادة التيار ولا تتناقص."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-24T23:08:04.862Z"}'::jsonb),
('mcq', 7, 0, 'الجهد ثابت 120 V، و$P = \frac{V^2}{R}$؛ فالخيار الحار يحتاج قدرة أكبر، أي مقاومة أصغر.', '["","عند جهد ثابت، المقاومة الأصغر تنتج حرارة أكثر لا أقل.","استعمل $P = I^2R$ كأن التيار ثابت، مع أن تصغير $R$ عند ثبات الجهد يزيد التيار؛ والعلاقة المناسبة عند ثبات الجهد $P = \\frac{V^2}{R}$.","تساوي الجهد لا يعني تساوي المقاومة؛ القدرتان مختلفتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-24T23:08:04.862Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عندما تتحرك شحنة $q$ خلال مقاومة يقل فرق جهدها بمقدار $V$، فتفقد طاقة مقدارها $qV$. وتتصادم الإلكترونات في أثناء حركتها مع ذرات المقاومة، فتزيد هذه التصادمات الطاقة الحركية للذرات، فترتفع درجة حرارة المقاومة؛ أي تتحول الطاقة الكهربائية إلى طاقة حرارية بمعدل يساوي القدرة. ومن الأجهزة المصممة لذلك: المدفأة الكهربائية، وصفيحة التسخين، وعنصر التسخين في مجفف الشعر، والمكواة، والفرن الكهربائي.', '["فقد الشحنة طاقة $qV$ عند عبور المقاومة","تصادم الإلكترونات مع ذرات المقاومة","زيادة الطاقة الحركية للذرات وارتفاع درجة الحرارة","جهازان صحيحان"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر التصادمات","marks":1},{"element":"زيادة الطاقة الحركية وارتفاع درجة الحرارة","marks":1},{"element":"ربط ذلك بتحول الطاقة الكهربائية","marks":1},{"element":"جهازان صحيحان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير مجهري كامل ومثالان صحيحان."},{"level":"2–3 درجات","description":"تفسير ناقص أو مثال واحد."},{"level":"1 درجة","description":"مثالان دون تفسير."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["القول إن الشحنات تُستهلك في المقاومة.","ذكر أجهزة تحوّل الطاقة إلى حركة (كالمروحة) مثالًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.863Z"}'::jsonb),
('essay', 2, null::int, null, null, 'بتعويض $V = IR$ في $P = IV$: $P = I(IR) = I^2R$، أي القدرة تساوي مربع التيار مضروبًا في المقاومة. وبتعويض $I = \frac{V}{R}$ في $P = IV$: $P = \frac{V}{R}V = \frac{V^2}{R}$، أي القدرة تساوي مربع الجهد مقسومًا على المقاومة. تُستعمل $P = I^2R$ عندما يكون التيار والمقاومة معلومين (أو عند المقارنة بتيار ثابت)، وتُستعمل $P = \frac{V^2}{R}$ عندما يكون الجهد والمقاومة معلومين (أو عند المقارنة بجهد ثابت).', '["اشتقاق $P = I^2R$","اشتقاق $P = \\frac{V^2}{R}$","متى تُستعمل كل علاقة"]'::jsonb, '["$P = IV$، و$V = IR$ ⇐ $P = I(IR) = I^2R$","$I = \\frac{V}{R}$ ⇐ $P = \\left(\\frac{V}{R}\\right)V = \\frac{V^2}{R}$"]'::jsonb, '[{"element":"اشتقاق $P = I^2R$","marks":1},{"element":"اشتقاق $P = \\frac{V^2}{R}$","marks":1},{"element":"توضيح شروط الاستعمال","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"اشتقاقان صحيحان وتوضيح سليم."},{"level":"2 درجتان","description":"اشتقاقان دون توضيح."},{"level":"1 درجة","description":"اشتقاق واحد."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["كتابة العلاقات دون خطوات التعويض.","الخلط بين $\\frac{V^2}{R}$ و$V^2R$."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-24T23:08:04.863Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $I = \frac{V}{R}$ ومع ثبات $R$ يقل التيار إلى النصف. (b) $P = \frac{V^2}{R}$، فتصبح $P'' = \frac{(V/2)^2}{R} = \frac{1}{4}\frac{V^2}{R}$؛ أي تقل القدرة إلى الربع. (c) لأن القدرة $P = IV$ حاصل ضرب التيار في الجهد، وكلاهما يقل إلى النصف، فيقل حاصل الضرب إلى $\frac{1}{2}\times\frac{1}{2} = \frac{1}{4}$.', '["التيار يقل إلى النصف","القدرة تقل إلى الربع","التفسير: كل من $I$ و$V$ يقل إلى النصف"]'::jsonb, '["$I'' = \\frac{V/2}{R} = \\frac{I}{2}$","$P'' = \\frac{(V/2)^2}{R} = \\frac{P}{4}$"]'::jsonb, '[{"element":"التغير في التيار","marks":1},{"element":"التغير في القدرة","marks":2},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابات صحيحة للأجزاء الثلاثة."},{"level":"2–3 درجات","description":"القدرة صحيحة دون تفسير، أو التيار والتفسير فقط."},{"level":"1 درجة","description":"التيار فقط."},{"level":"صفر","description":"لا إجابة أو القول إن القدرة تقل إلى النصف."}]'::jsonb, '["القول إن القدرة تقل إلى النصف.","افتراض ثبات التيار عند تغير الجهد."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-24T23:08:04.863Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C1-L2-O06') and x.type = v.type and x.number = v.number
