insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C1-L2-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ماذا يُسمّي المهندسون الكهربائيون الطاقة الحرارية غير المرغوب فيها المتولدة في أسلاك نقل الطاقة الكهربائية بمعدل $P = I^2R$؟', null, null, '["القدرة الضائعة $I^2R$","القدرة المنقولة $IV$","الكيلوواط.ساعة المستهلك","الطاقة الحرارية المفيدة"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 26–27 — القدرة الضائعة I²R'),
('mcq', 2, 'مقاومة السلك المستعمل لنقل التيار من محطة كهرباء إلى بيت تساوي 0.20 Ω لكل 1 km من طوله، والبيت يبعد عن المحطة 2.5 km. ما مقاومة أسلاك الدائرة التي تنقل التيار إلى البيت ثم تعيده إلى المحطة؟', null, null, '["$0.50\\ \\Omega$","$1.0\\ \\Omega$","$12.5\\ \\Omega$","$0.40\\ \\Omega$"]'::jsonb, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 27 — مقاومة أسلاك التوصيل'),
('mcq', 3, 'يمر تيار مقداره 30 A في أسلاك توصيل مقاومتها الكلية (ذهابًا وإيابًا) 1.0 Ω. ما مقدار القدرة الضائعة في الأسلاك؟', null, null, '["$30\\ \\text{W}$","$4.5\\times10^{2}\\ \\text{W}$","$9.0\\times10^{2}\\ \\text{W}$","$1.8\\times10^{3}\\ \\text{W}$"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 26–27 — القدرة الضائعة I²R'),
('mcq', 4, 'يبين الشكل الآتي محطة توليد تغذي منزلًا عبر سلكين مقاومة كل منهما 0.80 Ω، ويمر فيهما تيار مقداره 50 A. ما مقدار القدرة الضائعة في السلكين معًا؟', null, '[{"src":"qimg/phys32/c1l2-o07-line.svg","alt":"محطة توليد (مربع بداخله دائرة) على اليسار، يخرج منها سلكان أفقيان متوازيان (سلك ذهاب علوي وسلك إياب سفلي) يصلان إلى منزل على اليمين. في منتصف كل سلك رمز مقاومة متعرجة مكتوب عندها 0.80 Ω. فوق السلك العلوي قرب المنزل سهم نحو اليمين مكتوب عنده I = 50 A."}]'::jsonb, '["$2.0\\times10^{3}\\ \\text{W}$","$80\\ \\text{W}$","$6.4\\times10^{3}\\ \\text{W}$","$4.0\\times10^{3}\\ \\text{W}$"]'::jsonb, 'تطبيق', 'استنتاج من شكل', 'متوسط', 'الكتاب ص 27 — مثال الأسلاك والطبّاخ'),
('mcq', 5, 'تنقل محطة قدرة مقدارها 2.0 MW بجهد 100 kV عبر خط مقاومته الكلية 5.0 Ω. ما مقدار القدرة الضائعة في الخط؟', null, null, '["$2.0\\times10^{9}\\ \\text{W}$","$2.0\\times10^{3}\\ \\text{W}$","$1.0\\times10^{2}\\ \\text{W}$","$4.0\\times10^{2}\\ \\text{W}$"]'::jsonb, 'تحليل', 'حل مسألة', 'صعب', 'الكتاب ص 26–27 — القدرة الضائعة I²R'),
('mcq', 6, 'أيّ العلاقات الآتية تعطي القدرة الضائعة $P_{\text{w}}$ في أسلاك خط نقل مقاومتها الكلية $R_{\text{w}}$، إذا كانت القدرة المنقولة $P$ وجهد النقل $V$؟', null, null, '["$P_{\\text{w}} = \\frac{V^2}{R_{\\text{w}}}$","$P_{\\text{w}} = \\frac{P^2}{R_{\\text{w}}}$","$P_{\\text{w}} = \\left(\\frac{P}{V}\\right)^2R_{\\text{w}}$","$P_{\\text{w}} = \\left(\\frac{P}{V}\\right)R_{\\text{w}}$"]'::jsonb, 'تحليل', 'اختيار علاقة', 'صعب', 'الكتاب ص 26–27 — القدرة الضائعة I²R'),
('mcq', 7, 'تُنقل قدرة مقدارها 500 kW بجهد 25 kV عبر خط مقاومته الكلية 2.0 Ω. ما النسبة المئوية للقدرة الضائعة في الخط إلى القدرة المنقولة؟', null, null, '["$0.0016\\%$","$0.16\\%$","$0.0080\\%$","$160\\%$"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 26–27 — القدرة الضائعة I²R'),
('essay', 1, 'عرّف القدرة الضائعة $I^2R$. ثم افترض أن بيتًا ريفيًا يبعد 4.0 km عن محطة الكهرباء كما في الشكل الآتي، وأن مقاومة سلك النقل 0.25 Ω لكل 1 km، وأن طبّاخًا كهربائيًا في البيت يسحب تيارًا مقداره 30 A. احسب: (a) مقاومة أسلاك الذهاب والإياب. (b) القدرة الضائعة في الأسلاك.', null, '[{"src":"qimg/phys32/c1l2-o07-rural.svg","alt":"محطة توليد (مربع بداخله دائرة) على اليسار، يخرج منها سلكان أفقيان متوازيان (ذهاب وإياب) يصلان إلى منزل على اليمين، وفي كل سلك رمز مقاومة متعرجة يمثل مقاومة السلك. تحت السلكين سهم مزدوج الرأس مكتوب تحته 4.0 km يمثل المسافة بين المحطة والمنزل."}]'::jsonb, null, 'تطبيق', 'تعريف وحساب', 'سهل', 'الكتاب ص 27 — مقاومة أسلاك التوصيل والقدرة الضائعة'),
('essay', 2, 'تُنقل قدرة كهربائية مقدارها 500 kW عبر خط مقاومته الكلية 4.0 Ω. احسب التيار في الخط والقدرة الضائعة ونسبتها المئوية إلى القدرة المنقولة عندما يكون جهد النقل: (a) 10 kV. (b) 100 kV. ثم (c) استنتج أثر رفع الجهد عشرة أمثال في القدرة الضائعة.', null, null, null, 'تحليل', 'مقارنة كمية', 'متوسط', 'الكتاب ص 26–27 — القدرة الضائعة I²R'),
('essay', 3, 'في بيت ريفي تبلغ القدرة الضائعة في أسلاك التوصيل 1.8 kW عند تشغيل طبّاخ كهربائي. اقترح مهندس حلّين: (1) استبدال الأسلاك بأخرى غليظة مقاومتها نصف مقاومة الأسلاك الحالية، (2) نقل القدرة نفسها بضعف الجهد مع بقاء الأسلاك نفسها. احسب القدرة الضائعة في كل حل، وقوّم أيّ الحلين أفضل.', null, null, null, 'تقويم', 'تقويم حلول', 'صعب', 'الكتاب ص 27 — تقليل الفقد في أسلاك النقل')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
