from (values
('mcq', 1, 0, 'الطاقة الحرارية غير المرغوب فيها الناتجة عن نقل الطاقة الكهربائية في الأسلاك تُسمّى القدرة الضائعة $I^2R$.', '["","القدرة المنقولة هي ما يُراد إيصاله إلى المستهلك، لا ما يضيع حرارةً.","الكيلوواط.ساعة وحدة طاقة، وليس اسم الطاقة الضائعة.","هذه الحرارة غير مرغوب فيها، فلا تُعدّ مفيدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-24T23:08:04.864Z"}'::jsonb),
('mcq', 2, 1, 'يقطع التيار المسافة ذهابًا وإيابًا: $R = 2(2.5\ \text{km})(0.20\ \Omega/\text{km}) = 1.0\ \Omega$.', '["حسب مقاومة سلك الذهاب فقط ونسي سلك العودة.","","قسم المسافة على المقاومة لكل كيلومتر بدل الضرب.","ضرب المقاومة لكل كيلومتر في 2 فقط وأهمل المسافة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.864Z"}'::jsonb),
('mcq', 3, 2, '$P = I^2R = (30\ \text{A})^2(1.0\ \Omega) = 9.0\times10^{2}\ \text{W}$.', '["لم يربّع التيار.","استعمل نصف المقاومة (سلك واحد)، مع أن 1.0 Ω هي مقاومة السلكين معًا.","","ضاعف المقاومة مرة أخرى مع أنها تشمل الذهاب والإياب أصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-24T23:08:04.864Z"}'::jsonb),
('mcq', 4, 3, 'المقاومة الكلية للسلكين $= 2(0.80\ \Omega) = 1.6\ \Omega$، و$P = I^2R = (50\ \text{A})^2(1.6\ \Omega) = 4.0\times10^{3}\ \text{W}$.', '["حسب الضياع في سلك واحد فقط.","لم يربّع التيار: $(50)(1.6) = 80$.","ربّع حاصل ضرب التيار في المقاومة $(IR)^2$ فربّع المقاومة أيضًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-24T23:08:04.865Z"}'::jsonb),
('mcq', 5, 1, 'التيار في الخط $I = \frac{P}{V} = \frac{2.0\times10^{6}\ \text{W}}{1.0\times10^{5}\ \text{V}} = 20\ \text{A}$، والقدرة الضائعة $I^2R = (20\ \text{A})^2(5.0\ \Omega) = 2.0\times10^{3}\ \text{W}$.', '["طبّق $\\frac{V^2}{R}$ بجهد النقل 100 kV، وهو ليس فرق الجهد بين طرفي أسلاك الخط؛ فالناتج أكبر من القدرة المنقولة نفسها.","","لم يربّع التيار: $(20)(5.0) = 100$.","ربّع التيار ونسي الضرب في المقاومة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (52%)"}],"at":"2026-11-24T23:08:04.865Z"}'::jsonb),
('mcq', 6, 2, 'التيار في الخط $I = \frac{P}{V}$، والقدرة الضائعة في الأسلاك $I^2R_{\text{w}} = \left(\frac{P}{V}\right)^2R_{\text{w}}$؛ وهي تقل برفع جهد النقل.', '["جهد النقل $V$ ليس فرق الجهد بين طرفي الأسلاك، فلا يصلح في $\\frac{V^2}{R}$ هنا.","قسم مربع القدرة المنقولة على المقاومة؛ والصواب ضرب مربع التيار $\\frac{P}{V}$ في المقاومة، والوحدات هنا لا تعطي واطًا.","","هذا حاصل ضرب التيار في المقاومة، وهو فرق الجهد بين طرفي الأسلاك لا القدرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-24T23:08:04.865Z"}'::jsonb),
('mcq', 7, 1, '$I = \frac{5.0\times10^{5}\ \text{W}}{2.5\times10^{4}\ \text{V}} = 20\ \text{A}$، والضياع $(20)^2(2.0) = 800\ \text{W}$، والنسبة $\frac{800}{5.0\times10^{5}}\times100\% = 0.16\%$.', '["نسي الضرب في 100 لتحويل الكسر إلى نسبة مئوية.","","لم يربّع التيار فحسب الضياع 40 W.","قسم 800 W على 500 دون تحويل الكيلوواط إلى واط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (52%)"}],"at":"2026-11-24T23:08:04.865Z"}'::jsonb),
('essay', 1, null::int, null, null, 'القدرة الضائعة $I^2R$: الطاقة الحرارية غير المرغوب فيها المتولدة في أسلاك نقل الطاقة الكهربائية بمعدل $P = I^2R$. (a) $R = 2(4.0\ \text{km})(0.25\ \Omega/\text{km}) = 2.0\ \Omega$. (b) $P = I^2R = (30\ \text{A})^2(2.0\ \Omega) = 1.8\times10^{3}\ \text{W}$.', '["التعريف","مقاومة الأسلاك 2.0 Ω (ذهاب وإياب)","القدرة الضائعة $1.8\\times10^{3}\\ \\text{W}$"]'::jsonb, '["$R = 2\\times4.0\\times0.25 = 2.0\\ \\Omega$","$P = (30)^2(2.0) = 1800\\ \\text{W}$"]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"حساب المقاومة مع مراعاة الذهاب والإياب","marks":1},{"element":"حساب القدرة الضائعة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح وحسابان صحيحان."},{"level":"2–3 درجات","description":"تعريف مع حساب واحد، أو حسابان مع إغفال سلك العودة."},{"level":"1 درجة","description":"التعريف فقط."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["إغفال سلك العودة.","عدم تربيع التيار."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.866Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $I = \frac{5.0\times10^{5}}{1.0\times10^{4}} = 50\ \text{A}$، الضياع $= (50)^2(4.0) = 1.0\times10^{4}\ \text{W}$، أي $2.0\%$. (b) $I = \frac{5.0\times10^{5}}{1.0\times10^{5}} = 5.0\ \text{A}$، الضياع $= (5.0)^2(4.0) = 1.0\times10^{2}\ \text{W}$، أي $0.020\%$. (c) رفع الجهد عشرة أمثال قلل التيار إلى العُشر، فقلّت القدرة الضائعة إلى $\frac{1}{100}$ لأنها تتناسب مع مربع التيار.', '["عند 10 kV: 50 A و$1.0\\times10^{4}\\ \\text{W}$ و2.0%","عند 100 kV: 5.0 A و$1.0\\times10^{2}\\ \\text{W}$ و0.020%","الاستنتاج: الضياع يقل إلى جزء من مئة"]'::jsonb, '["$I = \\frac{P}{V}$","$P_{\\text{w}} = I^2R$","النسبة $= \\frac{I^2R}{P}\\times100\\%$"]'::jsonb, '[{"element":"حسابات الحالة (a)","marks":2},{"element":"حسابات الحالة (b)","marks":2},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابات كاملة صحيحة واستنتاج مرتبط بمربع التيار."},{"level":"3–4 درجات","description":"حسابات صحيحة لحالة واحدة كاملة وجزئية للأخرى، أو دون استنتاج."},{"level":"1–2 درجة","description":"حساب التيارين فقط."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["استعمال $\\frac{V^2}{R}$ بجهد النقل.","الاستنتاج أن الضياع يقل إلى العُشر فقط."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-24T23:08:04.866Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الحل (1): التيار نفسه والمقاومة نصفها، و$P = I^2R$ ⇐ يقل الضياع إلى النصف: $0.90\ \text{kW}$. الحل (2): مضاعفة الجهد مع ثبات القدرة تجعل التيار نصفه، والضياع يتناسب مع $I^2$ ⇐ يقل إلى الربع: $0.45\ \text{kW}$. التقويم: الحل (2) أفضل لأنه يقلل الضياع أكثر، ولا يحتاج إلى أسلاك غليظة باهظة الثمن وثقيلة؛ لذا تعتمد شركات الكهرباء على رفع الجهد في النقل.', '["الحل (1): 0.90 kW","الحل (2): 0.45 kW","الحكم بأفضلية رفع الجهد","التسويغ: الضياع يتناسب مع $I^2$، والأسلاك الغليظة مكلفة"]'::jsonb, '["الحل (1): $P_1 = \\frac{1.8}{2} = 0.90\\ \\text{kW}$","الحل (2): $I'' = \\frac{I}{2}$ ⇐ $P_2 = \\frac{1.8}{4} = 0.45\\ \\text{kW}$"]'::jsonb, '[{"element":"حساب الحل (1)","marks":1},{"element":"حساب الحل (2)","marks":1},{"element":"الحكم","marks":1},{"element":"التسويغ","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان وحكم مسوّغ بالفيزياء والتكلفة."},{"level":"2–3 درجات","description":"حسابان صحيحان دون تسويغ كافٍ."},{"level":"1 درجة","description":"حكم دون حساب."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["عدّ الحلين متكافئين.","القول إن مضاعفة الجهد تضاعف الضياع."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-24T23:08:04.866Z"}'::jsonb)
