from (values
('mcq', 1, 'لماذا يُوصل الطبّاخ الكهربائي وسخّان الماء الكهربائي بدائرة جهدها 220 V بدلًا من دائرة جهدها 127 V؟', null, null, '["لأن الجهد الأعلى يقلل القدرة التي يستهلكها الجهاز","لأن الجهاز يحتاج تيارًا أكبر عند الجهد الأعلى","لأن القدرة نفسها تُنقل بتيار أقل فتقل سخونة الأسلاك","لأن مقاومة أسلاك المنزل تزداد عند الجهد الأعلى"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 29 — السؤال 32'),
('mcq', 2, 'طبّاخ كهربائي قدرته 4400 W. ما مقدار التيار الذي يسحبه عند تشغيله على 220 V، وعند تشغيل طبّاخ له القدرة نفسها على 127 V؟', null, null, '["35 A عند 220 V و20 A عند 127 V","20 A عند 220 V و35 A عند 127 V","20 A عند كلا الجهدين","35 A عند كلا الجهدين"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 27 — جهد التمديدات المنزلية'),
('mcq', 3, 'يعمل جهازان لهما القدرة نفسها، أحدهما على 127 V والآخر على 220 V، وتمديداتهما المنزلية لها المقاومة نفسها. كم مرة تقريبًا تكون القدرة الضائعة في تمديدات الجهاز الذي يعمل على 127 V أكبر منها في تمديدات الآخر؟', null, null, '["1.7 مرة","1.0 مرة","0.33 مرة","3.0 مرة"]'::jsonb, 'تطبيق', 'استدلال كمي', 'متوسط', 'الكتاب ص 29 — السؤال 32'),
('mcq', 4, 'أيّ الأجهزة الآتية يُفضَّل توصيله بدائرة جهدها 220 V؟', null, null, '["سخّان الماء الكهربائي","شاحن الهاتف المحمول","المذياع الصغير","الساعة الرقمية"]'::jsonb, 'فهم', 'تطبيق حياتي', 'سهل', 'الكتاب ص 28 — الأجهزة التي تزيد قدرتها على 1000 W'),
('mcq', 5, 'يستغرق سخّان ماء جهده 127 V زمنًا مقداره 3.0 h لتسخين حجم معيّن من الماء. ما الزمن اللازم لإنجاز المهمة نفسها باستخدام سخّان آخر جهده 220 V مع بقاء التيار نفسه؟', null, null, '["5.2 h","1.7 h","3.0 h","1.0 h"]'::jsonb, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 25 — المسألة 24'),
('mcq', 6, 'يبين المنحنى الآتي التيار اللازم لتشغيل جهاز قدرته ثابتة 4.4 kW عند جهود تشغيل مختلفة. ما الذي يمكن استنتاجه منه بشأن تشغيل الجهاز على 220 V بدلًا من 127 V؟', null, '[{"src":"qimg/phys32/c1l2-o08-i-v.svg","alt":"منحنى بياني: المحور الأفقي «الجهد (V)» من 100 إلى 250 بتدريج كل 25، والمحور الرأسي «التيار (A)» من 0 إلى 50 بتدريج كل 10. منحنى أزرق متناقص يبدأ عند نحو 40 A عند 110 V وينتهي عند نحو 17.6 A عند 250 V، وعليه نقطتان معلّمتان: الأولى عند 127 V (نحو 34.6 A)، والثانية عند 220 V و20 A. يمثل المنحنى التيار اللازم لتشغيل جهاز قدرته ثابتة 4.4 kW عند جهود مختلفة."}]'::jsonb, '["يزداد التيار عند 220 V فتزداد القدرة الضائعة في الأسلاك","يقل التيار عند 220 V فتقل القدرة الضائعة في الأسلاك","يبقى التيار ثابتًا فلا فرق بين الجهدين","يقل التيار عند 220 V فتقل القدرة التي يستهلكها الجهاز"]'::jsonb, 'تحليل', 'استنتاج من منحنى', 'متوسط', 'الكتاب ص 29 — السؤال 32'),
('mcq', 7, 'سلك تمديد في منزل يتحمل تيارًا أقصاه 25 A دون أن يسخن سخونة خطرة. يُراد تشغيل طبّاخ قدرته 4000 W عبر هذا السلك. أيّ العبارات الآتية صحيحة؟', null, null, '["يصلح تشغيله على الجهدين لأن قدرته واحدة","يصلح تشغيله على 127 V فقط لأن تياره أقل","لا يصلح تشغيله على أي من الجهدين","يصلح تشغيله على 220 V فقط لأن تياره نحو 18 A"]'::jsonb, 'تحليل', 'اتخاذ قرار', 'صعب', 'الكتاب ص 27 — جهد التمديدات المنزلية'),
('essay', 1, 'فسّر لماذا يتم توصيل الطبّاخ الكهربائي وسخّان الماء الكهربائي بدائرة جهدها 220 V بدلًا من دائرة جهدها 127 V، مستعينًا بالعلاقتين $P = IV$ و$P = I^2R$.', null, null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 29 — السؤال 32'),
('essay', 2, 'سخّان ماء قدرته 3.0 kW، ومقاومة أسلاك التمديد التي تغذيه 0.20 Ω (ذهابًا وإيابًا). احسب التيار في الأسلاك والقدرة الضائعة فيها عندما يعمل السخّان: (a) على 127 V. (b) على 220 V. ثم (c) قارن بين النتيجتين وفسّر.', null, null, null, 'تحليل', 'مقارنة كمية', 'متوسط', 'الكتاب ص 27 — جهد التمديدات المنزلية'),
('essay', 3, 'اذكر ثلاثة تطبيقات منزلية شائعة تستخدم فرق جهد 220 V بدلًا من 127 V، ثم قوّم العواقب المترتبة على تشغيل مثل هذه التطبيقات على جهد 127 V.', null, null, null, 'تقويم', 'تقويم', 'صعب', 'الكتاب ص 31 — الفيزياء في الحياة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
