insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'هذه أجهزة ذات قدرة كبيرة، ومن $P = IV$ فإن الجهد الأعلى يوفر القدرة نفسها بتيار أقل، فتقل القدرة الضائعة $I^2R$ في أسلاك المنزل وتقل سخونتها.', '["القدرة اللازمة لتشغيل الجهاز واحدة؛ الذي يتغير هو التيار.","عند ثبات القدرة يقل التيار برفع الجهد ولا يزداد.","","مقاومة الأسلاك لا تعتمد على الجهد المطبق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-11-24T23:08:04.867Z"}'::jsonb),
('mcq', 2, 1, '$I = \frac{P}{V}$: عند 220 V $I = \frac{4400}{220} = 20\ \text{A}$، وعند 127 V $I = \frac{4400}{127} = 35\ \text{A}$ تقريبًا.', '["عكس القيمتين؛ الجهد الأقل يتطلب تيارًا أكبر.","","التيار يتغير مع الجهد عند ثبات القدرة.","التيار يتغير مع الجهد عند ثبات القدرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-24T23:08:04.867Z"}'::jsonb),
('mcq', 3, 3, '$I = \frac{P}{V}$، فنسبة التيارين $\frac{220}{127} = 1.73$، والضياع $I^2R$ يتناسب مع مربع التيار: $(1.73)^2 = 3.0$ مرة.', '["قارن التيارين ولم يربّع النسبة.","افترض أن الضياع لا يتغير مع أن التيار تغير.","قلب النسبة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-24T23:08:04.867Z"}'::jsonb),
('mcq', 4, 0, 'سخّان الماء جهاز ذو قدرة كبيرة (أكثر من 1000 W)؛ فتشغيله على 220 V يقلل التيار المار في الأسلاك، أما الأجهزة الأخرى فقدرتها صغيرة وتيارها صغير.', '["","قدرة الشاحن صغيرة، فتياره صغير عند أي من الجهدين.","قدرة المذياع صغيرة، فلا حاجة إلى جهد أعلى لتقليل تياره.","قدرة الساعة الرقمية صغيرة جدًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-24T23:08:04.867Z"}'::jsonb),
('mcq', 5, 1, 'الطاقة اللازمة واحدة: $E = IVt$، ومع بقاء التيار نفسه $V_1t_1 = V_2t_2$، إذن $t_2 = \frac{(127\ \text{V})(3.0\ \text{h})}{220\ \text{V}} = 1.7\ \text{h}$.', '["قلب النسبة فضرب في $\\frac{220}{127}$ بدل $\\frac{127}{220}$.","","الجهد الأعلى مع التيار نفسه يعني قدرة أكبر، فيقل الزمن.","افترض ثبات مقاومة السخّان فربّع نسبة الجهدين، مع أن المعطى ثبات التيار، فالطاقة $IVt$ تتناسب مع الجهد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-24T23:08:04.867Z"}'::jsonb),
('mcq', 6, 1, 'المنحنى متناقص: التيار عند 220 V (20 A) أقل منه عند 127 V (نحو 35 A)، والقدرة الضائعة في الأسلاك $I^2R$ تقل بنقصان التيار، أما قدرة الجهاز فثابتة 4.4 kW.', '["المنحنى متناقص، فالتيار يقل بزيادة الجهد.","","التيار يتغير بوضوح بين النقطتين.","قدرة الجهاز ثابتة 4.4 kW؛ الذي يقل هو التيار والضياع في الأسلاك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-24T23:08:04.868Z"}'::jsonb),
('mcq', 7, 3, 'عند 220 V: $I = \frac{4000}{220} = 18\ \text{A}$ (أقل من 25 A)، وعند 127 V: $I = \frac{4000}{127} = 31\ \text{A}$ (أكبر من 25 A)؛ فيصلح على 220 V فقط.', '["تساوي القدرة لا يعني تساوي التيار؛ التيار على 127 V نحو 31 A.","التيار على 127 V أكبر لا أقل (نحو 31 A).","التيار على 220 V نحو 18 A وهو أقل من الحد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-24T23:08:04.868Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الطبّاخ وسخّان الماء من الأجهزة ذات القدرة الكبيرة (أكثر من 1000 W). من $P = IV$ يلزم لتوفير هذه القدرة تيار $I = \frac{P}{V}$، فكلما ارتفع الجهد قل التيار اللازم. والطاقة الحرارية المتولدة في أسلاك المنزل تتولد بمعدل $I^2R$، فتقليل التيار يقلل سخونة الأسلاك والطاقة الضائعة فيها، ويقلل الحاجة إلى أسلاك غليظة؛ لذلك تُوصل هذه الأجهزة بدائرة 220 V.', '["الأجهزة ذات قدرة كبيرة","الجهد الأعلى ⇐ تيار أقل للقدرة نفسها","تيار أقل ⇐ ضياع $I^2R$ وسخونة أقل في الأسلاك"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر أن قدرتها كبيرة","marks":1},{"element":"توظيف $P = IV$","marks":1},{"element":"توظيف $P = I^2R$ والاستنتاج","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل يوظف العلاقتين."},{"level":"2 درجتان","description":"يذكر تقليل التيار دون ربطه بالضياع في الأسلاك."},{"level":"1 درجة","description":"عبارة عامة صحيحة جزئيًا."},{"level":"صفر","description":"لا إجابة أو تفسير خاطئ."}]'::jsonb, '["القول إن الجهد الأعلى يقلل استهلاك الجهاز للطاقة.","القول إن الجهد الأعلى يزيد التيار."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-11-24T23:08:04.868Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $I = \frac{3000}{127} = 23.6\ \text{A}$، والضياع $= (23.6)^2(0.20) = 1.1\times10^{2}\ \text{W}$. (b) $I = \frac{3000}{220} = 13.6\ \text{A}$، والضياع $= (13.6)^2(0.20) = 37\ \text{W}$. (c) الضياع على 127 V أكبر بنحو 3.0 مرة، لأن التيار أكبر بنحو 1.7 مرة والضياع يتناسب مع مربع التيار.', '["عند 127 V: نحو 24 A ونحو 112 W","عند 220 V: نحو 14 A ونحو 37 W","النسبة نحو 3 مع التفسير بمربع التيار"]'::jsonb, '["$I = \\frac{P}{V}$","$P_{\\text{w}} = I^2R$","$\\frac{112}{37} \\approx 3.0$"]'::jsonb, '[{"element":"حسابات الحالة (a)","marks":2},{"element":"حسابات الحالة (b)","marks":2},{"element":"المقارنة والتفسير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة ومقارنة مفسرة."},{"level":"3–4 درجات","description":"حسابات صحيحة دون تفسير أو مع خطأ حسابي واحد."},{"level":"1–2 درجة","description":"التياران فقط."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["استعمال $\\frac{V^2}{R}$ بجهد المصدر ومقاومة الأسلاك.","عدم تربيع التيار."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-24T23:08:04.868Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تطبيقات تستخدم 220 V: الطبّاخ الكهربائي، وسخّان الماء، ومكيّف الهواء، ومجففة الملابس (أجهزة قدرتها كبيرة). عواقب تشغيلها على 127 V: يلزم لتوفير القدرة نفسها تيار أكبر بنحو 1.7 مرة ($I = \frac{P}{V}$)، فتزداد القدرة الضائعة $I^2R$ في الأسلاك نحو 3 مرات، فتسخن الأسلاك أكثر وقد يحدث خطر حريق، ويلزم استعمال أسلاك أغلظ وأغلى ثمنًا، وتزداد الطاقة المهدرة. لذا فالتشغيل على 220 V أكثر أمانًا واقتصادًا.', '["ثلاثة تطبيقات صحيحة","تيار أكبر عند 127 V","ضياع وسخونة أكبر في الأسلاك وخطر","الحاجة إلى أسلاك أغلظ وتكلفة أكبر، وحكم ختامي"]'::jsonb, '[]'::jsonb, '[{"element":"ثلاثة تطبيقات","marks":1},{"element":"التيار الأكبر","marks":1},{"element":"الضياع والسخونة والخطر","marks":1},{"element":"التكلفة والحكم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تطبيقات صحيحة وتقويم شامل مسوّغ."},{"level":"2–3 درجات","description":"تطبيقات صحيحة مع عاقبة واحدة."},{"level":"1 درجة","description":"تطبيقات فقط."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["ذكر أجهزة ذات قدرة صغيرة.","القول إن الجهاز لن يعمل إطلاقًا على 127 V."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-24T23:08:04.869Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C1-L2-O08') and x.type = v.type and x.number = v.number
