('mcq', 1, 'مصباح كهربائي قدرته 60.0 W وكفاءته 15%. ما مقدار الطاقة التي يحوّلها إلى ضوء كل دقيقة؟', null, null, '["$5.4\\times10^{2}\\ \\text{J}$","$3.1\\times10^{3}\\ \\text{J}$","$9.0\\ \\text{J}$","$3.6\\times10^{3}\\ \\text{J}$"]'::jsonb, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 25 — المسألة 22 (كفاءة المصباح)'),
('mcq', 2, 'مصباح كهربائي قدرته 75.0 W وكفاءته 20%؛ أي أن 20% فقط من الطاقة الكهربائية تتحول إلى طاقة ضوئية. ما مقدار الطاقة الحرارية التي ينتجها المصباح كل دقيقة؟', null, null, '["$9.0\\times10^{2}\\ \\text{J}$","$3.6\\times10^{3}\\ \\text{J}$","$4.5\\times10^{3}\\ \\text{J}$","$60\\ \\text{J}$"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 25 — المسألة 22 (كفاءة المصباح)'),
('mcq', 3, 'يبين الشكل الآتي مخطط سريان الطاقة في محرك كهربائي يستقبل 1200 J من الطاقة الكهربائية كل ثانية. إذا كانت كفاءة المحرك 80%، فما مقدار الطاقة التي تتحول إلى طاقة حرارية كل ثانية؟', null, '[{"src":"qimg/phys32/c1l2-o09-motor.svg","alt":"مخطط سريان الطاقة: سهم برتقالي عريض من اليسار مكتوب فوقه «طاقة كهربائية داخلة» وبداخله «1200 J كل ثانية» يدخل مربعًا مكتوبًا فيه «محرك كهربائي». يخرج من المربع سهم أخضر نحو اليمين مكتوب فوقه «طاقة ميكانيكية مفيدة» وبداخله علامة استفهام، وسهم أحمر منحنٍ نحو الأسفل مكتوب عنده «طاقة حرارية» وتحته علامة استفهام."}]'::jsonb, '["960 J","1200 J","1500 J","240 J"]'::jsonb, 'تطبيق', 'استنتاج من شكل', 'سهل', 'الكتاب ص 23 — تحولات الطاقة في المحرك'),
('mcq', 4, 'محرك كهربائي يستهلك قدرة 1100 W وكفاءته 80%. ما مقدار الطاقة الميكانيكية المفيدة التي يعطيها خلال 10.0 min؟', null, null, '["$1.3\\times10^{5}\\ \\text{J}$","$6.6\\times10^{5}\\ \\text{J}$","$5.3\\times10^{5}\\ \\text{J}$","$8.8\\times10^{3}\\ \\text{J}$"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 37 — السؤال 75'),
('mcq', 5, 'فرن ميكروويف يعمل على 120 V ويمر فيه تيار 12 A. كفاءة تحويله الطاقة الكهربائية إلى أشعة ميكروويف 75%، وكفاءة تحويل أشعة الميكروويف إلى حرارة في الماء 75% أيضًا. ما مقدار الطاقة التي تصل إلى الماء حرارةً كل ثانية؟', null, null, '["$6.3\\times10^{2}\\ \\text{J}$","$1.1\\times10^{3}\\ \\text{J}$","$1.4\\times10^{3}\\ \\text{J}$","$8.1\\times10^{2}\\ \\text{J}$"]'::jsonb, 'تحليل', 'حل مسألة', 'صعب', 'الكتاب ص 38 — السؤال 79'),
('mcq', 6, 'ما المقصود بقولنا إن كفاءة مصباح كهربائي 22%؟', null, null, '["أن 22% من الطاقة الكهربائية الواصلة إليه تتحول إلى ضوء","أن 22% من الطاقة الكهربائية الواصلة إليه تتحول إلى حرارة","أن المصباح يعمل 22% فقط من مدة تشغيله","أن قدرة المصباح تقل بنسبة 22% بعد إضاءته"]'::jsonb, 'فهم', 'مفهوم', 'متوسط', 'الكتاب ص 25 — المسألة 22 (كفاءة المصباح)'),
('mcq', 7, 'يُراد أن يعطي مصباح 900 J من الطاقة الضوئية كل دقيقة، وكفاءته 25%. ما القدرة الكهربائية التي يجب أن يستهلكها؟', null, null, '["$15\\ \\text{W}$","$60\\ \\text{W}$","$3.8\\ \\text{W}$","$3.6\\times10^{3}\\ \\text{W}$"]'::jsonb, 'تحليل', 'حل مسألة عكسية', 'صعب', 'الكتاب ص 25 — المسألة 22 (كفاءة المصباح)'),
('essay', 1, 'ما مقدار الطاقة المستنفدة في مصباح قدرته 40.0 W خلال ساعة واحدة؟ وإذا حوّل المصباح 12% من الطاقة الكهربائية إلى طاقة ضوئية، فما مقدار الطاقة الضوئية والطاقة الحرارية التي يولدهما خلال هذه الساعة؟', null, null, null, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 36 — السؤال 62'),
('essay', 2, 'يُشغّل محرك كهربائي مضخة لرفع الماء في مزرعة؛ فيرفع $1.50\times10^{4}\ \text{kg}$ من الماء رأسيًا مسافة 10.0 m كل ساعة. وُصل المحرك بمصدر جهد 220 V وكانت مقاومته في أثناء تشغيله 44.0 Ω. افترض أن $g = 9.80\ \text{m/s}^2$. احسب: (a) التيار المار في المحرك. (b) الطاقة الكهربائية التي يستهلكها في ساعة. (c) كفاءة المحرك.', null, null, null, 'تحليل', 'مسألة متعددة الخطوات', 'متوسط', 'الكتاب ص 37 — السؤال 75'),
('essay', 3, 'غلاية كهربائية قدرتها 2.0 kW، وتنتقل 80% من الطاقة الكهربائية التي تستهلكها إلى الماء على شكل حرارة. يُراد تسخين 1.5 kg من الماء من $25\ ^\circ\text{C}$ إلى $100\ ^\circ\text{C}$، والحرارة النوعية للماء $4180\ \text{J/kg}\cdot^\circ\text{C}$. احسب: (a) الطاقة الحرارية التي يجب أن يمتصها الماء. (b) الطاقة الكهربائية التي يجب أن تستهلكها الغلاية. (c) الزمن اللازم للتسخين.', null, null, null, 'تطبيق', 'مسألة متعددة الخطوات', 'صعب', 'الكتاب ص 25 — المسألة 23c')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C1-L2-O09') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'الطاقة الكهربائية في دقيقة $E = Pt = (60.0\ \text{W})(60\ \text{s}) = 3.6\times10^{3}\ \text{J}$، والضوئية $= 0.15\times3.6\times10^{3} = 5.4\times10^{2}\ \text{J}$.', '["","هذه الطاقة الحرارية (85%) لا الضوئية.","لم يحوّل الدقيقة إلى ثوانٍ.","هذه الطاقة الكهربائية الكلية قبل ضربها في الكفاءة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-24T23:08:04.869Z"}'::jsonb),
('mcq', 2, 1, 'الطاقة الكهربائية في دقيقة $= (75.0\ \text{W})(60\ \text{s}) = 4.5\times10^{3}\ \text{J}$، والحرارية $= (1 - 0.20)(4.5\times10^{3}) = 3.6\times10^{3}\ \text{J}$.', '["هذه الطاقة الضوئية (20%) لا الحرارية.","","هذه الطاقة الكهربائية الكلية.","لم يحوّل الدقيقة إلى ثوانٍ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-24T23:08:04.869Z"}'::jsonb),
('mcq', 3, 3, 'الطاقة الميكانيكية المفيدة $= 0.80\times1200 = 960\ \text{J}$، والباقي يتحول إلى حرارة: $1200 - 960 = 240\ \text{J}$.', '["هذه الطاقة الميكانيكية المفيدة لا الحرارية.","هذه الطاقة الكهربائية الداخلة كلها.","قسم 1200 على الكفاءة بدل الضرب فيها، فحصل على طاقة أكبر من الداخلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-24T23:08:04.870Z"}'::jsonb),
('mcq', 4, 2, 'الطاقة الكهربائية الداخلة $E = Pt = (1100\ \text{W})(600\ \text{s}) = 6.6\times10^{5}\ \text{J}$، والمفيدة $= 0.80\times6.6\times10^{5} = 5.3\times10^{5}\ \text{J}$.', '["هذه الطاقة الضائعة (20%) لا المفيدة.","هذه الطاقة الكهربائية الكلية قبل ضربها في الكفاءة.","","لم يحوّل الدقائق إلى ثوانٍ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-24T23:08:04.870Z"}'::jsonb),
('mcq', 5, 3, 'القدرة الكهربائية $P = IV = (12)(120) = 1440\ \text{W}$، والطاقة الواصلة إلى الماء كل ثانية $= (0.75)(0.75)(1440\ \text{J}) = 8.1\times10^{2}\ \text{J}$.', '["هذه الطاقة التي لا تصل إلى الماء، لا الواصلة إليه.","طبّق كفاءة واحدة فقط من المرحلتين.","هذه الطاقة الكهربائية الداخلة كلها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.870Z"}'::jsonb),
('mcq', 6, 0, 'الكفاءة نسبة الطاقة المفيدة إلى الطاقة الداخلة؛ فكفاءة 22% تعني أن 22% فقط من الطاقة الكهربائية تتحول إلى طاقة ضوئية، والباقي (78%) يتحول معظمه إلى طاقة حرارية.', '["","الحرارة في المصباح طاقة غير مفيدة، ونسبتها هنا 78%.","الكفاءة نسبة طاقة مفيدة، لا نسبة زمن.","الكفاءة لا تصف تغيّر القدرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-24T23:08:04.871Z"}'::jsonb),
('mcq', 7, 1, 'الطاقة الكهربائية اللازمة كل دقيقة $= \frac{900\ \text{J}}{0.25} = 3.6\times10^{3}\ \text{J}$، والقدرة $P = \frac{E}{t} = \frac{3.6\times10^{3}\ \text{J}}{60\ \text{s}} = 60\ \text{W}$.', '["قسم الطاقة الضوئية على الزمن وأهمل الكفاءة.","","ضرب في الكفاءة بدل القسمة عليها.","حسب الطاقة اللازمة ولم يقسمها على الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-24T23:08:04.871Z"}'::jsonb),
('essay', 1, null::int, null, null, '$E = Pt = (40.0\ \text{W})(3600\ \text{s}) = 1.44\times10^{5}\ \text{J}$. الطاقة الضوئية $= 0.12\times1.44\times10^{5} = 1.7\times10^{4}\ \text{J}$. الطاقة الحرارية $= 0.88\times1.44\times10^{5} = 1.3\times10^{5}\ \text{J}$.', '["الطاقة الكلية $1.44\\times10^{5}\\ \\text{J}$","الضوئية $1.7\\times10^{4}\\ \\text{J}$","الحرارية $1.3\\times10^{5}\\ \\text{J}$"]'::jsonb, '["$t = 1.0\\ \\text{h} = 3600\\ \\text{s}$","$E = 40.0\\times3600 = 1.44\\times10^{5}\\ \\text{J}$","الضوئية $= 0.12E = 1.73\\times10^{4}\\ \\text{J}$","الحرارية $= E - 0.12E = 1.27\\times10^{5}\\ \\text{J}$"]'::jsonb, '[{"element":"الطاقة الكلية","marks":1},{"element":"الطاقة الضوئية","marks":1},{"element":"الطاقة الحرارية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الحسابات الثلاثة صحيحة."},{"level":"2 درجتان","description":"حسابان صحيحان."},{"level":"1 درجة","description":"حساب واحد صحيح."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["نسيان تحويل الساعة إلى ثوانٍ.","عدّ الطاقة الحرارية 12%."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-24T23:08:04.871Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $I = \frac{V}{R} = \frac{220\ \text{V}}{44.0\ \Omega} = 5.00\ \text{A}$. (b) $P = IV = 1100\ \text{W}$، و$E = Pt = (1100\ \text{W})(3600\ \text{s}) = 3.96\times10^{6}\ \text{J}$. (c) الطاقة المفيدة $= mgh = (1.50\times10^{4})(9.80)(10.0) = 1.47\times10^{6}\ \text{J}$، والكفاءة $= \frac{1.47\times10^{6}}{3.96\times10^{6}}\times100\% = 37\%$.', '["التيار 5.00 A","الطاقة الكهربائية $3.96\\times10^{6}\\ \\text{J}$","الطاقة المفيدة $1.47\\times10^{6}\\ \\text{J}$","الكفاءة نحو 37%"]'::jsonb, '["$I = \\frac{220}{44.0} = 5.00\\ \\text{A}$","$E = (5.00)(220)(3600) = 3.96\\times10^{6}\\ \\text{J}$","$mgh = 1.47\\times10^{6}\\ \\text{J}$","الكفاءة $= \\frac{1.47}{3.96}\\times100\\% = 37\\%$"]'::jsonb, '[{"element":"التيار","marks":1},{"element":"الطاقة الكهربائية","marks":1},{"element":"الطاقة المفيدة","marks":1},{"element":"الكفاءة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"جميع الخطوات صحيحة."},{"level":"3–4 درجات","description":"خطأ في خطوة واحدة."},{"level":"1–2 درجة","description":"التيار والطاقة الكهربائية فقط."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["قسمة الطاقة الكهربائية على المفيدة (كفاءة أكبر من 100%).","نسيان تحويل الساعة إلى ثوانٍ."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.871Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $Q = mC\Delta T = (1.5)(4180)(75) = 4.7\times10^{5}\ \text{J}$. (b) $E = \frac{Q}{0.80} = 5.9\times10^{5}\ \text{J}$. (c) $t = \frac{E}{P} = \frac{5.88\times10^{5}\ \text{J}}{2.0\times10^{3}\ \text{W}} = 2.9\times10^{2}\ \text{s}$ (نحو 4.9 min).', '["الحرارة اللازمة $4.7\\times10^{5}\\ \\text{J}$","الطاقة الكهربائية $5.9\\times10^{5}\\ \\text{J}$ (قسمة على الكفاءة)","الزمن $2.9\\times10^{2}\\ \\text{s}$"]'::jsonb, '["$\\Delta T = 100 - 25 = 75\\ ^\\circ\\text{C}$","$Q = 1.5\\times4180\\times75 = 4.70\\times10^{5}\\ \\text{J}$","$E = \\frac{4.70\\times10^{5}}{0.80} = 5.88\\times10^{5}\\ \\text{J}$","$t = \\frac{5.88\\times10^{5}}{2000} = 294\\ \\text{s}$"]'::jsonb, '[{"element":"الحرارة اللازمة","marks":1},{"element":"الطاقة الكهربائية بالقسمة على الكفاءة","marks":2},{"element":"الزمن","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الخطوات صحيحة."},{"level":"2–3 درجات","description":"خطأ في استعمال الكفاءة (ضرب بدل قسمة)."},{"level":"1 درجة","description":"الحرارة اللازمة فقط."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["ضرب الطاقة اللازمة في الكفاءة بدل قسمتها عليها.","إهمال الكفاءة فيقل الزمن إلى 235 s."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-24T23:08:04.872Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
